Track the balance before and after collectFees() and only transfer the difference. Example fix:
```solidity
function _claimFees() internal returns (uint256 claimed0, uint256 claimed1) {
    if (!isForPair) return (0, 0);

    address _token0 = clPool.token0();
    address _token1 = clPool.token1();

    uint256 balance0Before = IERC20(_token0).balanceOf(address(this));
    uint256 balance1Before = IERC20(_token1).balanceOf(address(this));

    clPool.collectFees();

    claimed0 = IERC20(_token0).balanceOf(address(this)) - balance0Before;
    claimed1 = IERC20(_token1).balanceOf(address(this)) - balance1Before;
    // ... rest of function
}
```
Additionally, consider adding access control to restrict who can call claimFees().

Add access control to claimFees() to restrict it to authorized callers only, such as the DISTRIBUTION contract or a designated fee collector role:
```solidity
function claimFees() external nonReentrant onlyDistribution returns (uint256 claimed0, uint256 claimed1) {
    return _claimFees();
}
```
